WITH mortality_stats AS (SELECT subject_id, COUNT(*) filter (WHERE date_of_death IS NOT NULL) AS death_count, percent_rank() filter (WHERE date_of_death IS NOT NULL) AS death_percent_rank FROM mortality GROUP BY subject_id) SELECT percentile_cont(0.8) within GROUP (ORDER BY death_count) AS mortality_percentile, percent_rank() within GROUP (ORDER BY death_count) AS mortality_percent_rank, lag(death_count) OVER (PARTITION BY subject_id ORDER BY intime) AS previous_death_count FROM mortality_stats;